		got.Destruction == nil || got.Destruction.Operator != "李四" || got.Destruction.Location != "实验室B" {
		t.Fatalf("销毁详情与最后持有人、地点应原样保留: %+v", got)
	}
}

// TestOpenRejectsDestroyedCustodyDespiteOtherValidSamples 文件中另有正常
