	parent.History[0].Holder, parent.History[0].Location = "张三", "实验室A"
	parent.Destroyed.Operator, parent.Destroyed.Location = "张三", "实验室A"
	// 子样后来交接给王五、移到实验室C，并由王五在实验室C 销毁全部
	// 3.250；父子销毁信息互不一致却各自与自身最后记录一致。
